scripts.lcg:
def solve(inputs: dict) -> float:
    x = int(inputs['SEED'])
    a = int(inputs['A'])
    b = int(inputs['B'])
    m = int(inputs['M'])
    k = int(inputs['K'])
    for _ in range(k):
        x = (a * x + b) % m
    return float(x)

scripts.modpow:
def solve(inputs: dict) -> float:
    base = int(inputs['BASE'])
    exp = int(inputs['EXP'])
    mod = int(inputs['MOD'])
    return float(pow(base, exp, mod))

scripts.dotproduct:
def solve(inputs: dict) -> float:
    qs = inputs['QUANTITIES']
    ps = inputs['PRICES']
    total = sum(int(q) * int(p) for q, p in zip(qs, ps))
    print(f"Exact result: {total}")
    return float(total)

